import type { ReactNode } from "react";

/** Internal layout shared by domain panels. Shipped with its owning component. */
export function PanelHeader({
  icon,
  title,
  description,
  status,
  action,
  as: Heading = "h3",
}: {
  icon: ReactNode;
  title: string;
  description?: ReactNode;
  status?: ReactNode;
  action?: ReactNode;
  as?: "h2" | "h3";
}) {
  return (
    <div data-slot="panel-header" className="min-w-0">
      <div
        data-slot="panel-topline"
        className="grid min-w-0 grid-cols-[minmax(0,1fr)_auto] items-start gap-x-3 gap-y-2"
      >
        <div
          data-slot="panel-identity"
          className="flex min-w-0 items-start gap-3"
        >
          <span
            data-slot="panel-icon"
            aria-hidden="true"
            className="surface-control grid size-10 shrink-0 place-items-center rounded-full border bg-secondary text-secondary-foreground shadow-sm [&>svg]:size-4"
          >
            {icon}
          </span>
          <div
            data-slot="panel-heading"
            className="flex min-h-12 min-w-0 flex-col"
          >
            <Heading
              data-slot="panel-title"
              className="text-base font-medium leading-snug wrap-anywhere"
            >
              {title}
            </Heading>
            {description && (
              <p
                data-slot="panel-description"
                className="mt-1 text-sm leading-relaxed text-muted-foreground wrap-anywhere"
              >
                {description}
              </p>
            )}
          </div>
        </div>
        {(status != null || action != null) && (
          <div
            data-slot="panel-meta"
            className="ml-auto flex min-w-0 flex-wrap items-center justify-end gap-2 text-right text-sm text-muted-foreground"
          >
            {status != null && (
              <div data-slot="panel-status" className="min-w-0 wrap-anywhere">
                {status}
              </div>
            )}
            {action}
          </div>
        )}
      </div>
    </div>
  );
}

import type { ComponentProps } from "react";
import { PanelHeader } from "@/components/iot/internal/panel-header";

type PanelProps = ComponentProps<typeof PanelHeader> &
  Omit<ComponentProps<"section">, "title"> & {
    contentClassName?: string;
  };

/** Owns the surface, all four insets, header alignment and the content boundary. */
export function Panel({
  icon,
  title,
  description,
  status,
  action,
  as,
  className = "",
  contentClassName = "",
  children,
  ...props
}: PanelProps) {
  return (
    <section
      data-slot="panel"
      data-panel-layout=""
      className={`@container surface-raised grid min-w-0 gap-[var(--card-padding,24px)] rounded-xl border bg-card p-[var(--card-padding,24px)] text-card-foreground shadow-sm ${className}`}
      {...props}
    >
      <PanelHeader
        icon={icon}
        title={title}
        description={description}
        status={status}
        action={action}
        as={as}
      />
      <div
        data-slot="panel-content"
        className={`min-w-0 ${contentClassName || "space-y-5"}`}
      >
        {children}
      </div>
    </section>
  );
}

import { Panel } from "@/components/iot/internal/panel";
import { ShieldCheck } from "lucide-react";
import { timeLabel } from "@/lib/iot-model";
export type InterlockCondition = {
  id: string;
  label: string;
  state: "satisfied" | "blocked" | "unknown" | "stale";
  source: string;
  at: number | null;
  detail?: string;
};
const labels = {
  satisfied: "满足",
  blocked: "未满足",
  unknown: "未知",
  stale: "数据陈旧",
};
export function InterlockStatus({
  decision,
  reason,
  conditions,
  evaluatedAt,
}: {
  decision: "permitted" | "blocked" | "unknown";
  reason: string;
  conditions: InterlockCondition[];
  evaluatedAt: number | null;
}) {
  const title = {
    permitted: "许可已满足",
    blocked: "联锁阻止操作",
    unknown: "许可状态未知",
  }[decision];
  return (
    <Panel
      icon={<ShieldCheck />}
      title="许可与联锁"
      status={
        <span
          className={
            decision === "permitted" ? "text-success" : "text-warning-text"
          }
        >
          {title}
        </span>
      }
      aria-label="许可与联锁"
    >
      <p className="text-sm text-muted-foreground">{reason}</p>
      <div className="surface-inset p-4">
        <ul className="divide-y divide-border/40">
          {conditions.map((condition) => (
            <li key={condition.id} className="py-3 first:pt-0 last:pb-0">
              <details>
                <summary className="flex cursor-pointer items-center justify-between gap-3 text-sm">
                  <span>{condition.label}</span>
                  <span
                    className={
                      condition.state === "satisfied"
                        ? "text-success"
                        : "text-warning"
                    }
                  >
                    {labels[condition.state]}
                  </span>
                </summary>
                <div className="mt-3 space-y-2 text-sm text-muted-foreground">
                  <p>{condition.detail || "未提供补充说明"}</p>
                  <p>
                    {condition.source} · {timeLabel(condition.at)} UTC
                  </p>
                </div>
              </details>
            </li>
          ))}
        </ul>
        {!conditions.length && (
          <p className="text-sm text-muted-foreground">
            没有可显示的条件，不能据此视为许可。
          </p>
        )}
      </div>
      <p className="text-sm text-muted-foreground">
        判定来源：设备 / 控制服务 · {timeLabel(evaluatedAt)}{" "}
        UTC。界面展示上游判定，不自行授权。
      </p>
    </Panel>
  );
}
